std::string markdownToHtml(const std::string& markdown) {
    // Replace markdown syntax with HTML tags
    std::string html = markdown;
    std::regex markdownRegex(R"(
        <h1>Title</h1>
        <h2>Subtitle</h2>
        <h3>Subtitle</h3>
        <h4>Subtitle</h4>
        <h5>Subtitle</h5>
    )");

    // Replace markdown syntax with HTML tags
    std::regex_replace(html, markdown, markdownRegex);

    return html;
}
```

